{"query":"image search per-registry verdict outcome header nexus group member registry","repo_root":"/home/anthoni/projects/workspace-entire/anthnel/devdesk","commit":"75be68354f508694a57e5d135d8bf976044ba87c","tree":"88bf912838bc4a8927edf399d74d5cf557eb542f","profile":"full","results":[{"rank":1,"score":42.4286,"file_path":"internal/registrymgr/nexus.go","start_line":117,"end_line":162,"focus_line":121,"snippet_start_line":121,"snippet_end_line":162,"symbol_start_line":121,"symbol_end_line":148,"language":"Go","kind":"method","symbol_id":"local/devdesk:Go:internal/registrymgr/nexus.go:method:NexusDetector.fetchGroupMembers","symbol_name":"fetchGroupMembers","qualified_name":"NexusDetector.fetchGroupMembers","signature":"func (n *NexusDetector) fetchGroupMembers(ctx context.Context, host, repoName, format string, info RegistryInfo) []GroupMember","signals":["path","body","signature","symbol-name","graph:callers","complete-symbol","contiguous-span"],"snippet":"func (n *NexusDetector) fetchGroupMembers(ctx context.Context, host, repoName, format string, info RegistryInfo) []GroupMember {
	if format == "" {
		format = "docker"
	}
	endpoint := fmt.Sprintf("%s/service/rest/v1/repositories/%s/group/%s", host, format, repoName)
	body, err := n.nexusGET(ctx, endpoint, info)
	if err != nil {
		// When auth is present but the request fails, retry anonymously.
		// Some Nexus instances allow anonymous read of the group admin endpoint.
		if info.Username != "" && info.Password != "" {
			anonInfo := RegistryInfo{URL: info.URL, ManagementURL: info.ManagementURL}
			body, err = n.nexusGET(ctx, endpoint, anonInfo)
		}
	}
	if err != nil {
		log.Printf("INFO [registrymgr/nexus] members unreachable %q: %v — account may lack nx-repository-admin privilege; run 'docker login %s' with an admin account", endpoint, err, host)
		return nil
	}
	var result struct {
		Group struct {
			MemberNames []string `json:"memberNames"`
		} `json:"group"`
	}
	if err := json.Unmarshal(body, &result); err != nil {
		return nil
	}
	return memberList(info.URL, result.Group.MemberNames)
}

// memberList turns the names a group declares into addresses.
func memberList(dockerURL string, names []string) []GroupMember {
	members := make([]GroupMember, 0, len(names))
	for _, name := range names {
		url, prefix := memberAddress(dockerURL, name)
		members = append(members, GroupMember{
			Alias:      cleanMemberAlias(name),
			URL:        url,
			RepoPrefix: prefix,
		})
	}
	return members
}","merged_ranks":[1,2]},{"rank":2,"score":39.0211,"file_path":"internal/ui/oci_resources/commands.go","start_line":483,"end_line":512,"focus_line":483,"snippet_start_line":483,"snippet_end_line":512,"symbol_start_line":483,"symbol_end_line":512,"language":"Go","kind":"function","symbol_id":"local/devdesk:Go:internal/ui/oci_resources/commands.go:function:detectRegistryGroupCmd","symbol_name":"detectRegistryGroupCmd","qualified_name":"detectRegistryGroupCmd","signature":"func detectRegistryGroupCmd(reg config.RegistryItem, password string) tea.Cmd","signals":["graph:calls","graph:incoming","graph:callers","complete-symbol"],"snippet":"func detectRegistryGroupCmd(reg config.RegistryItem, password string) tea.Cmd {
	return func() tea.Msg {
		ctx, cancel := context.WithTimeout(context.Background(), 8*time.Second)
		defer cancel()

		username := reg.Username
		// D12: a registry the user marked anonymous is probed anonymously.
		// Docker keys credentials by host, so without this gate the credentials
		// stored for any registry on that host went out to all of them — which,
		// for a Nexus instance, is every repository it serves.
		if config.UsesCredentials(config.ResolveAuthMode(reg, nil)) {
			username, password = discoveryCreds(reg, username, password)
		} else {
			username, password = "", ""
		}

		info := registrymgr.RegistryInfo{
			Provider:      reg.Provider,
			URL:           reg.URL,
			ManagementURL: reg.ManagementURL,
			Username:      username,
			Password:      password,
		}
		members, err := registrymgr.DetectGroup(ctx, info)
		if err == nil {
			cacheGroupMembers(reg.Slug, members)
		}
		return RegistryGroupDetectedMsg{RegistryURL: reg.URL, Slug: reg.Slug, Members: members, Err: err}
	}
}"},{"rank":3,"score":36.6068,"file_path":"internal/registrymgr/detector.go","start_line":49,"end_line":53,"focus_line":53,"snippet_start_line":49,"snippet_end_line":53,"symbol_start_line":48,"symbol_end_line":54,"language":"Go","kind":"type","symbol_id":"local/devdesk:Go:internal/registrymgr/detector.go:type:Detector","symbol_name":"Detector","qualified_name":"Detector","signature":"Detector interface { // Provider returns the declared provider this detector serves. Provider() string // DetectGroup returns the group members when the registry is a group repo. // Returns nil, nil when the registry is not a group (not an error). DetectGroup(ctx context.Context, info RegistryInfo) ([]GroupMember, error) }","signals":["path","body","signature","symbol-usage"],"snippet":"	// Provider returns the declared provider this detector serves.
